type Pool struct {
	mu    sync.Mutex
	items []*Conn
	closed bool
}
func (p *Pool) Get() *Conn {
	if p.closed { return nil }
	p.mu.Lock(); defer p.mu.Unlock()
	...
}
func (p *Pool) Put(c *Conn) {
	p.mu.Lock(); defer p.mu.Unlock()
	if p.closed { c.Close(); return }
	p.items = append(p.items, c)
}
func (p *Pool) Close() { p.closed = true; ... }

