func (c *Cache) Get(k string) any {
	c.mu.RLock(); defer c.mu.RUnlock()
	if v, ok := c.m[k]; ok && !c.stale(v) { return v.val }
	return c.refreshLocked(k)
}
func (c *Cache) refreshLocked(k string) any {
	v := c.loader(k)
	c.Set(k, v)
	return v
}

