def dedupe(rows):
    out = []
    for r in rows:
        if not any(near_dup(r, o) for o in out):
            out.append(r)
    return out

def near_dup(a, b):
    return levenshtein(a['name'], b['name']) <= 2 and a['zip'] == b['zip']

